# Met le projet MangaStudio a niveau (34 fichiers) sans git apply.
# Usage : depuis le dossier mangastudio -> python mettre_a_niveau.py
import base64, os, sys, zlib, subprocess
FICHIERS = {
"frontend/src/lib/i18n.ts": "",
".gitignore": "",
"backend/app/pipeline/runner.py": "",
"backend/scripts/controle_securite.py": "",
"frontend/src/components/admin.tsx": "",
"frontend/src/components/ink.tsx": "",
"frontend/src/content/concours.ts": "",
"frontend/src/content/contact.ts": "",
"frontend/src/content/faq.ts": "",
"frontend/src/content/publication.ts": "",
"frontend/src/content/styles.ts": "",
"frontend/src/lib/admin.ts": "",
"frontend/src/lib/api.ts": "",
"frontend/src/lib/concours.ts": "",
"frontend/src/lib/galerie.ts": "",
"frontend/src/routes/concours.$slug.tsx": "",
"frontend/src/routes/concours.index.tsx": "",
"frontend/src/routes/connexion.tsx": "",
"frontend/src/routes/contact.tsx": "",
"frontend/src/routes/episodes.$id.tsx": "",
"frontend/src/routes/faq.tsx": "",
"frontend/src/routes/gagner.tsx": "",
"frontend/src/routes/galerie.$id.tsx": "",
"frontend/src/routes/galerie.index.tsx": "",
"frontend/src/routes/index.tsx": "",
"frontend/src/routes/inscription.tsx": "",
"frontend/src/routes/mon-avis.tsx": "",
"frontend/src/routes/mot-de-passe-oublie.tsx": "",
"frontend/src/routes/regles-publication.tsx": "",
"frontend/src/routes/series.$id.tsx": "",
"frontend/src/routes/soutenir.tsx": "",
"frontend/src/routes/styles.tsx": "",
"frontend/src/routes/verifier.tsx": "",
"vps/sauvegarde.sh": ""
}
racine = os.path.dirname(os.path.abspath(__file__))
if not os.path.isdir(os.path.join(racine, "frontend")) or not os.path.isdir(os.path.join(racine, "backend")):
    sys.exit("Place ce fichier a la racine du projet mangastudio (a cote de frontend et backend).")
for chemin, contenu in FICHIERS.items():
    cible = os.path.join(racine, *chemin.split("/"))
    os.makedirs(os.path.dirname(cible) or racine, exist_ok=True)
    with open(cible, "wb") as f:
        f.write(zlib.decompress(base64.b64decode(contenu)))
    print("ecrit :", chemin)
patch = os.path.join(racine, "a_ranger", "mise_a_niveau.patch")
if os.path.exists(patch):
    os.remove(patch)
print()
print(len(FICHIERS), "fichiers ecrits. Verification :")
subprocess.call([sys.executable, os.path.join(racine, "verifier_fichiers.py")], cwd=racine)